/**
 * @file apps/mobile/src/context/CartContext.tsx
 * @description React Context managing customer cart state and financial line-item calculations.
 *
 * ARCHITECTURAL DESIGN & INVARIANTS:
 * 1. Line-Item Determinism: Multiple portions of the same dish with identical options and instructions
 *    are grouped into a single line item. The cart item ID is generated by deterministically sorting
 *    chosen option IDs to prevent fragmentation: `${item.id}_${sortedOptionsKey}_${instructions}`.
 * 2. Integer Financial Arithmetic: Line totals and running sub-totals are computed strictly in integer pesewas
 *    using calculateLineTotalPesewas() from @sika/shared, matching the server-side pricing algorithm.
 * 3. Immutable State Transitions: Quantity modifications, additions, and removals produce new immutable array
 *    references, ensuring seamless React render cycles.
 */

import React, { createContext, useContext, useState, useMemo } from "react";
import { MenuItemDTO, calculateLineTotalPesewas } from "@sika/shared";

/**
 * Snapshot of a selected dish customization option (e.g. "Smoky Jollof Rice", "+GH₵ 0.00").
 */
export interface SelectedOptionChoice {
  optionId: string;
  optionName: string;
  priceDeltaPesewas: number;
}

/**
 * Individual cart entry representing a customized portion of a menu item.
 */
export interface CartItem {
  id: string; // Deterministic hash: `${menuItemId}_${sortedOptionIds}_${specialInstructions}`
  menuItem: MenuItemDTO;
  quantity: number;
  selectedOptions: SelectedOptionChoice[];
  specialInstructions?: string;
  unitPricePesewas: number; // Base price + options delta
  subtotalPesewas: number; // unitPricePesewas * quantity
}

interface CartContextType {
  items: CartItem[];
  addItem: (
    item: MenuItemDTO,
    quantity: number,
    selectedOptions?: SelectedOptionChoice[],
    specialInstructions?: string
  ) => void;
  removeItem: (cartItemId: string) => void;
  updateQuantity: (cartItemId: string, newQuantity: number) => void;
  clearCart: () => void;
  cartSubtotalPesewas: number;
  totalItemCount: number;
}

const CartContext = createContext<CartContextType | undefined>(undefined);

/**
 * CartProvider wraps the mobile application to provide reactive cart state and math across all screens.
 */
export function CartProvider({ children }: { children: React.ReactNode }) {
  const [items, setItems] = useState<CartItem[]>([]);

  /**
   * Adds a portion of a dish to the cart. If an identical configuration already exists, increments its quantity.
   */
  const addItem = (
    item: MenuItemDTO,
    quantity: number = 1,
    selectedOptions: SelectedOptionChoice[] = [],
    specialInstructions?: string
  ) => {
    const optionsDelta = selectedOptions.reduce((acc, opt) => acc + opt.priceDeltaPesewas, 0);
    const unitPricePesewas = item.basePricePesewas + optionsDelta;

    // Generate deterministic key to group identical configurations
    const optionIdsKey = selectedOptions
      .map((o) => o.optionId)
      .sort()
      .join("-");
    const cartItemId = `${item.id}_${optionIdsKey}_${specialInstructions || ""}`;

    setItems((prev) => {
      const existingIndex = prev.findIndex((i) => i.id === cartItemId);
      if (existingIndex > -1) {
        const updated = [...prev];
        const newQty = updated[existingIndex].quantity + quantity;
        updated[existingIndex] = {
          ...updated[existingIndex],
          quantity: newQty,
          subtotalPesewas: calculateLineTotalPesewas(item.basePricePesewas, newQty, optionsDelta),
        };
        return updated;
      }

      return [
        ...prev,
        {
          id: cartItemId,
          menuItem: item,
          quantity,
          selectedOptions,
          specialInstructions,
          unitPricePesewas,
          subtotalPesewas: calculateLineTotalPesewas(item.basePricePesewas, quantity, optionsDelta),
        },
      ];
    });
  };

  /**
   * Removes a line item from the cart by its composite ID.
   */
  const removeItem = (cartItemId: string) => {
    setItems((prev) => prev.filter((i) => i.id !== cartItemId));
  };

  /**
   * Adjusts the portion count of an existing cart item. If quantity reaches 0 or less, removes the item.
   */
  const updateQuantity = (cartItemId: string, newQuantity: number) => {
    if (newQuantity <= 0) {
      removeItem(cartItemId);
      return;
    }

    setItems((prev) =>
      prev.map((item) => {
        if (item.id === cartItemId) {
          const optionsDelta = item.selectedOptions.reduce(
            (acc, opt) => acc + opt.priceDeltaPesewas,
            0
          );
          return {
            ...item,
            quantity: newQuantity,
            subtotalPesewas: calculateLineTotalPesewas(
              item.menuItem.basePricePesewas,
              newQuantity,
              optionsDelta
            ),
          };
        }
        return item;
      })
    );
  };

  /**
   * Flushes all items from the cart.
   */
  const clearCart = () => {
    setItems([]);
  };

  /**
   * Running subtotal of all items in integer pesewas.
   */
  const cartSubtotalPesewas = useMemo(() => {
    return items.reduce((sum, item) => sum + item.subtotalPesewas, 0);
  }, [items]);

  /**
   * Total portion count across all line items (e.g. 2 Jollof + 1 Pizza = 3).
   */
  const totalItemCount = useMemo(() => {
    return items.reduce((sum, item) => sum + item.quantity, 0);
  }, [items]);

  return (
    <CartContext.Provider
      value={{
        items,
        addItem,
        removeItem,
        updateQuantity,
        clearCart,
        cartSubtotalPesewas,
        totalItemCount,
      }}
    >
      {children}
    </CartContext.Provider>
  );
}

/**
 * Custom React hook consuming the cart context.
 *
 * @throws Error - If invoked outside of a <CartProvider> subtree
 */
export function useCart() {
  const context = useContext(CartContext);
  if (!context) {
    throw new Error("useCart must be used within a CartProvider");
  }
  return context;
}
